```vue /home/codx-junior-projects/codx-junior/client/src/components/desktop/Desktop.vue
<script setup>
import { DockviewVue } from 'dockview-vue'
import Window from './Window.vue'
</script>
<template>
  <dockview-vue
    class="dockview-theme-abyss w-full h-full"
    @ready="onReady"
    :components="registeredComponents"
  />
</template>
<script>
export default {
  name: 'Desktop',
  components: {
    'dockview-vue': DockviewVue,
    'window': Window
  },
  props: {
    // Initial panels to render on mount
    panels: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      dockviewApi: null,
      // Map of registered component names to Vue components
      registeredComponents: {
        'window': Window
      }
    }
  },
  methods: {
    // Store dockview API and add initial panels
    onReady(event) {
      this.dockviewApi = event.api
      this.panels.forEach(panel => this.addPanel(panel))
      this.$emit('ready', event.api)
    },

    // Add a new panel to the desktop
    addPanel({ id, title, component = 'window', position }) {
      if (!this.dockviewApi) return
      this.dockviewApi.addPanel({
        id,
        title,
        component,
        position
      })
    },

    // Remove a panel by id
    removePanel(id) {
      if (!this.dockviewApi) return
      const panel = this.dockviewApi.getPanel(id)
      panel && this.dockviewApi.removePanel(panel)
    },

    // Register a new component so it can be used as a panel
    registerComponent(name, component) {
      this.registeredComponents = {
        ...this.registeredComponents,
        [name]: component
      }
    }
  }
}
</script>
```

### Usage Example

```vue /home/codx-junior-projects/codx-junior/client/src/views/DesktopView.vue
<script setup>
import Desktop from '@/components/desktop/Desktop.vue'
import MyTool from '@/components/tools/MyTool.vue'
</script>
<template>
  <div class="w-screen h-screen bg-gray-900">
    <Desktop
      :panels="initialPanels"
      @ready="onDesktopReady"
      ref="desktop"
    />
  </div>
</template>
<script>
export default {
  name: 'DesktopView',
  data() {
    return {
      initialPanels: [
        { id: 'panel_1', title: 'Tool 1' },
        { id: 'panel_2', title: 'Tool 2', position: { referencePanel: 'panel_1', direction: 'right' } }
      ]
    }
  },
  methods: {
    onDesktopReady(api) {
      // Register custom components after desktop is ready
      this.$refs.desktop.registerComponent('my-tool', MyTool)
    },

    openNewPanel() {
      this.$refs.desktop.addPanel({ id: 'panel_3', title: 'New Panel', component: 'my-tool' })
    }
  }
}
</script>
```

### Key Design Decisions:

| Feature | Description |
|---|---|
| `Window.vue` | Wrapper with a slot for any content, exposes `params.api` |
| `Desktop.vue` | Manages dockview lifecycle, panel registration and API |
| `registerComponent` | Dynamically add new panel types at runtime |
| `addPanel / removePanel` | Public methods to control panels from parent |
| `@ready` emit | Exposes raw dockview API to parent if needed |
